import json
import threading
import time
import socket
import os

# Global list to store registered devices
registered_devices = []
lock = threading.Lock()

def handle_client(client_socket, client_address):
    """Handle a single client connection"""
    try:
        # Read the registration data from client
        try:
            content = client_socket.recv(1024).decode()
            data = json.loads(content)
        except Exception:
            content = ""
            data = None

        if not data:
            error_response = {"status": "error", "message": "No valid data received"}
            try:
                client_socket.send(json.dumps(error_response).encode())
            except:
                pass
            client_socket.close()
            return

        device_id = data.get('device_id')
        mac_address = data.get('mac_address')

        # Validate MAC address format - must contain DE:AD:BE:EF:**:** where the last two parts are based on device_id
        # The pattern is DE:AD:BE:EF followed by two hex parts that are dynamic based on device id
        if mac_address is None or not isinstance(mac_address, str):
            # This is a faulty device - log error and close
            error_log = f"Error: Faulty device attempting registration without proper MAC address. device_id={device_id}"
            print(error_log)
            error_response = {"status": "error", "message": "Invalid MAC address format"}
            try:
                client_socket.send(json.dumps(error_response).encode())
            except:
                pass
            client_socket.close()
            return

        # Check if MAC starts with DE:AD:BE:EF
        if not mac_address.startswith("DE:AD:BE:EF:"):
            error_log = f"Error: Faulty device with invalid MAC format. device_id={device_id}, mac={mac_address}"
            print(error_log)
            error_response = {"status": "error", "message": "Invalid MAC address format - must start with DE:AD:BE:EF"}
            try:
                client_socket.send(json.dumps(error_response).encode())
            except:
                pass
            client_socket.close()
            return

        # Check that MAC has the right format (DE:AD:BE:EF:xx:xx)
        parts = mac_address.split(':')
        if len(parts) != 6 or parts[0] != "DE" or parts[1] != "AD" or parts[2] != "BE" or parts[3] != "EF":
            error_log = f"Error: Faulty device with invalid MAC format. device_id={device_id}, mac={mac_address}"
            print(error_log)
            error_response = {"status": "error", "message": "Invalid MAC address format - must be DE:AD:BE:EF:xx:xx"}
            try:
                client_socket.send(json.dumps(error_response).encode())
            except:
                pass
            client_socket.close()
            return

        # This is a valid device registration
        # Register it
        device_info = {
            "device_id": device_id,
            "mac_address": mac_address
        }
        with lock:
            registered_devices.append(device_info)

        # Send success response
        response = {"status": "registered", "details": {"mac_address": mac_address, "device_id": device_id}}
        try:
            client_socket.send(json.dumps(response).encode())
        except:
            pass

    except Exception as e:
        error_log = f"Error handling client: {str(e)}"
        print(error_log)
    finally:
        try:
            client_socket.close()
        except:
            pass

def start_server():
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind(('0.0.0.0', 12345))
    server_socket.listen()

    print("Server started, waiting for connections...")
    start_time = time.time()

    while time.time() - start_time < 60:
        try:
            client_socket, client_address = server_socket.accept()
            # Handle the client in a new thread for concurrency
            thread = threading.Thread(target=handle_client, args=(client_socket, client_address))
            thread.daemon = True
            thread.start()
        except Exception as e:
            pass  # Ignore errors during accepting

    # After 60 seconds, stop listening and save results
    server_socket.close()
    print("Server stopped after 60 seconds.")

